const EXP=[['everyday','Everyday','Chat, dự án và công cụ đơn giản'],['workspace','Workspace','Nhiệm vụ, phê duyệt và tiến độ trực tiếp'],['studio','Studio','Tệp, terminal, diff và hoạt động'],['expert','Expert','Toàn bộ trung tâm điều khiển backend']];
const VI_EXPERIENCE_NAMES={everyday:'Phổ thông',workspace:'Không gian làm việc',studio:'Studio',expert:'Chuyên gia'};
const VI_THEME_DESCRIPTIONS={nocturne:'Đen tím',obsidian:'Đen thuần',graphite:'Tối trung tính',aurora:'Phổ màu hỗn hợp',snow:'Sáng tinh gọn',paper:'Sáng ấm',system:'Theo hệ điều hành'};
const VI_THEME_NAMES={nocturne:'Đêm tím',obsidian:'Đen tuyền',graphite:'Than chì',aurora:'Cực quang',snow:'Tuyết',paper:'Giấy',system:'Theo hệ thống'};
const THEMES=[['nocturne','Nocturne','Dark violet'],['obsidian','Obsidian','Pure black'],['graphite','Graphite','Neutral dark'],['aurora','Aurora','Mixed spectral'],['snow','Snow','Clean light'],['paper','Paper','Warm light'],['system','System','Follow operating system']];
const ACCENTS=['violet','blue','cyan','rose','amber','emerald'];
function language(state){const v=at(state.draft,'general.language');if(v==='vi'||v==='en')return v;return globalThis.document?.documentElement?.dataset?.language??'en'}
function titleFor(field,lang){return lang==='vi'?(VI_FIELD[field.path]??field.title):field.title}
function categoryTitle(category,lang){return lang==='vi'?(VI_CATEGORY[category.id]??category.title):category.title}
function categoryDesc(category,lang){return lang==='vi'?(VI_DESC[category.id]??category.description):category.description}
function sourceLabel(source,lang){if(lang!=='vi')return source;return ({defaults:'mặc định',user:'người dùng',project:'dự án',local:'máy này',policy:'chính sách'}[source]??source)}
function statusLabel(message,lang){if(lang!=='vi')return message;const raw=String(message??'');const exact={'Settings loaded.':'Đã tải cài đặt.','Settings are ready.':'Cài đặt đã sẵn sàng.','Unsaved changes.':'Có thay đổi chưa lưu.','Loading settings…':'Đang tải cài đặt…','Saving settings…':'Đang lưu cài đặt…','Settings were not saved.':'Không thể lưu cài đặt.','Settings failed to load.':'Không thể tải cài đặt.','Refreshing provider accounts…':'Đang làm mới tài khoản provider…','Provider account status refreshed.':'Đã làm mới trạng thái tài khoản provider.','Provider account refresh failed.':'Không thể làm mới trạng thái tài khoản provider.','Everyday experience selected.':'Đã chọn tầng Phổ thông.','Workspace experience selected.':'Đã chọn tầng Không gian làm việc.','Studio experience selected.':'Đã chọn tầng Studio.','Expert experience selected.':'Đã chọn tầng Chuyên gia.'};if(exact[raw])return exact[raw];let match=raw.match(/^Model discovery completed for (.+)\.$/);if(match)return `Đã khám phá model cho ${match[1]}.`;match=raw.match(/^Model discovery failed for (.+)\.$/);if(match)return `Khám phá model thất bại cho ${match[1]}.`;match=raw.match(/^Discovering models for (.+)…$/);if(match)return `Đang khám phá model cho ${match[1]}…`;match=raw.match(/^Provider (.+) configured\.$/);if(match)return `Đã thiết lập provider ${match[1]}.`;match=raw.match(/^Provider (.+) was not configured\.$/);if(match)return `Không thể thiết lập provider ${match[1]}.`;match=raw.match(/^Configuring provider (.+)…$/);if(match)return `Đang thiết lập provider ${match[1]}…`;match=raw.match(/^Opening account login for (.+)…$/);if(match)return `Đang mở đăng nhập tài khoản ${match[1]}…`;match=raw.match(/^Continue sign-in for (.+) in the browser\.$/);if(match)return `Tiếp tục đăng nhập ${match[1]} trong trình duyệt.`;match=raw.match(/^Provider sign-in failed for (.+)\.$/);if(match)return `Đăng nhập provider ${match[1]} thất bại.`;match=raw.match(/^Signing out of (.+)…$/);if(match)return `Đang đăng xuất ${match[1]}…`;match=raw.match(/^Signed out of (.+)\.$/);if(match)return `Đã đăng xuất ${match[1]}.`;match=raw.match(/^Provider sign-out failed for (.+)\.$/);if(match)return `Đăng xuất provider ${match[1]} thất bại.`;match=raw.match(/^Model (.+) added to (.+)\.$/);if(match)return `Đã thêm model ${match[1]} vào ${match[2]}.`;match=raw.match(/^Model (.+) was not added\.$/);if(match)return `Không thể thêm model ${match[1]}.`;match=raw.match(/^Adding model (.+)…$/);if(match)return `Đang thêm model ${match[1]}…`;return raw.replace('Settings saved to user scope.','Đã lưu cài đặt cho người dùng.').replace('All user overrides reset.','Đã đặt lại toàn bộ tùy chỉnh người dùng.')}
function modelOptions(state,selected,lang='en'){const profiles=state.models?.models??[];const options=[`<option value="auto"${selected==='auto'||!selected?' selected':''}>${lang==='vi'?'Tự động — để Nolane định tuyến':'Auto — let Nolane route'}</option>`];for(const p of profiles){const value=p.key??`${p.providerId}/${p.modelId}`;options.push(`<option value="${esc(value)}"${value===selected?' selected':''}>${esc(p.displayName??p.modelId)} · ${esc(p.providerId)}</option>`)}return options.join('')}
function input(field,value,state,lang){const common=`data-setting-path="${esc(field.path)}" id="setting-${esc(field.path)}"`;const unavailable=field.scope&&!field.scope.includes(state.layer)?' disabled aria-disabled="true"':'';if(field.type==='boolean')return `<button type="button" class="setting-toggle" role="switch" aria-checked="${Boolean(value)}" ${common}${unavailable}><span class="setting-toggle__track" aria-hidden="true"><span></span></span><span class="setting-toggle__label">${Boolean(value)?(lang==='vi'?'Bật':'On'):(lang==='vi'?'Tắt':'Off')}</span></button>`;if(field.type==='select')return `<select ${common}${unavailable}>${(field.options??[]).map(o=>`<option value="${esc(o)}"${o===value?' selected':''}>${esc(labelOption(o,lang))}</option>`).join('')}</select>`;if(field.type==='number')return `<div class="setting-number"><input type="number" value="${esc(value??'')}" min="${esc(field.min)}" max="${esc(field.max)}" step="${esc(field.step??1)}" ${common}${unavailable}>${field.suffix?`<span>${esc(lang==='vi'?(VI_SUFFIX[field.suffix]??field.suffix):field.suffix)}</span>`:''}</div>`;if(field.type==='model')return `<select ${common}${unavailable}>${modelOptions(state,value,lang)}</select>`;return `<input type="text" value="${esc(value??'')}" ${common}${unavailable}>`}
function appearanceShowcase(state,lang){const theme=at(state.draft,'appearance.theme')??'nocturne';const accent=at(state.draft,'appearance.accent')??'violet';return `<div class="appearance-showcase"><div class="theme-gallery">${THEMES.map(([id,name,desc])=>`<button type="button" data-setting-choice data-setting-path="appearance.theme" data-setting-value="${id}" aria-pressed="${theme===id}"><span class="theme-preview" data-preview-theme="${id}"><i></i><b></b><em></em></span><strong>${lang==='vi'?(VI_THEME_NAMES[id]??name):name}</strong><small>${lang==='vi'?(VI_THEME_DESCRIPTIONS[id]??desc):desc}</small></button>`).join('')}</div><div class="accent-picker"><span>${lang==='vi'?'Màu nhấn':'Accent color'}</span>${ACCENTS.map(id=>`<button type="button" data-setting-choice data-setting-path="appearance.accent" data-setting-value="${id}" aria-label="${lang==='vi'?(VI_OPTIONS[id]??id):id}" aria-pressed="${accent===id}" data-preview-accent="${id}"></button>`).join('')}</div></div>`}
function languageShowcase(state,lang){const value=at(state.draft,'general.language')??'system';return `<div class="language-cards"><button type="button" data-setting-choice data-setting-path="general.language" data-setting-value="en" aria-pressed="${value==='en'}"><strong>English</strong><small>${lang==='vi'?'Giao diện tiếng Anh':'English interface'}</small></button><button type="button" data-setting-choice data-setting-path="general.language" data-setting-value="vi" aria-pressed="${value==='vi'}"><strong>${lang==='vi'?'Tiếng Việt':'Vietnamese'}</strong><small>${lang==='vi'?'Giao diện tiếng Việt':'Vietnamese interface'}</small></button><button type="button" data-setting-choice data-setting-path="general.language" data-setting-value="system" aria-pressed="${value==='system'}"><strong>${lang==='vi'?'Theo hệ thống':'System'}</strong><small>${lang==='vi'?'Dùng ngôn ngữ hệ điều hành':'Follow operating system'}</small></button></div>`}
function renderCategory(category,state,lang){const rows=category.fields.map(field=>{const value=at(state.draft,field.path);const source=state.provenance?.[field.path];const unavailable=field.scope&&!field.scope.includes(state.layer);const metadata=[field.path,source?(lang==='vi'?`từ ${sourceLabel(source,lang)}`:`from ${source}`):null,field.locked?(lang==='vi'?'do chính sách bảo mật quản lý':'security managed'):null,unavailable?(lang==='vi'?`không khả dụng trong phạm vi ${labelOption(state.layer,lang)}`:`not available in ${state.layer} scope`):null,field.restart?(lang==='vi'?'cần khởi động lại':'restart required'):null].filter(Boolean).join(' · ');return `<div class="setting-row" data-setting-level="${esc(field.level??'standard')}" data-setting-path-row="${esc(field.path)}"><div class="setting-copy"><label for="setting-${esc(field.path)}">${esc(titleFor(field,lang))}</label>${field.description?`<p>${esc(field.description)}</p>`:''}<small>${esc(metadata)}</small></div><div class="setting-control">${input(field,value,state,lang)}</div></div>`}).join('');const modelPanel=category.id==='models'?renderModelProfilesPanel({models:state.models?.models??[],providers:state.providers??[],providerLogin:state.providerLogin},{experience:state.experience,comparison:state.modelComparison,dossiers:state.modelDossiers,lang}):'';const special=category.id==='appearance'?appearanceShowcase(state,lang):category.id==='general'?languageShowcase(state,lang):category.id==='diagnostics'?`<div class="recovery-card"><span>${icon('warning',{size:18})}</span><div><strong>${lang==='vi'?'Giao diện phục hồi cũ':'Legacy recovery interface'}</strong><p>${lang==='vi'?'Mở UI v2 chỉ khi cần phục hồi hoặc truy cập center chưa được chuyển đổi.':'Open UI v2 only for recovery or specialist centers not yet migrated.'}</p></div><a href="/legacy-ui/" target="_blank">${lang==='vi'?'Mở giao diện phục hồi':'Open recovery UI'}</a></div>`:'';return `<section class="settings-section" id="settings-${esc(category.id)}" data-settings-category="${esc(category.id)}"><header><p class="settings-section__eyebrow">${category.level==='research'?(lang==='vi'?'Chuyên gia':'Expert'):(lang==='vi'?'Cài đặt':'Settings')}</p><h2>${esc(categoryTitle(category,lang))}</h2><p>${esc(categoryDesc(category,lang)??'')}</p></header>${special}<div class="settings-card">${rows||`<p class="settings-empty">${lang==='vi'?'Mục này chỉ có thao tác và chẩn đoán, không có giá trị cần chỉnh.':'This category contains actions and diagnostics rather than editable values.'}</p>`}</div>${modelPanel}</section>`}
function scopeOptions(state,lang){const disabled=state.projectId==null;return `<label class="settings-layer"><span>${lang==='vi'?'Phạm vi lưu':'Save scope'}</span><select data-settings-layer><option value="user"${state.layer==='user'?' selected':''}>${lang==='vi'?'Người dùng':'User'}</option><option value="project"${state.layer==='project'?' selected':''}${disabled?' disabled':''}>${lang==='vi'?'Dự án':'Project'}</option><option value="local"${state.layer==='local'?' selected':''}${disabled?' disabled':''}>${lang==='vi'?'Máy này':'This machine'}</option></select></label>`}
export function renderSettingsView(state={}){const lang=language(state);if(state.status==='loading')return `<section class="settings-loading" aria-busy="true"><h1>${lang==='vi'?'Cài đặt':'Settings'}</h1><p role="status" aria-live="polite">${lang==='vi'?'Đang tải cài đặt…':'Loading settings…'}</p></section>`;if(state.status==='error')return `<section class="settings-error"><h1>${lang==='vi'?'Cài đặt':'Settings'}</h1><p role="alert">${esc(state.errors?.[0]?.message??(lang==='vi'?'Không thể tải cài đặt':'Unable to load settings'))}</p><button data-settings-action="retry">${lang==='vi'?'Thử lại':'Retry'}</button><p class="sr-only" role="status" aria-live="polite">${esc(state.statusMessage??'Settings failed to load.')}</p></section>`;const categories=state.visibleCategories??[];const exp=normalizeExperience(state.experience);return `<section class="settings-center" data-experience-level="${esc(exp)}"><aside class="settings-nav" aria-label="${lang==='vi'?'Danh mục cài đặt':'Settings categories'}"><a href="#/" class="settings-back" data-route="/">← ${lang==='vi'?'Quay lại ứng dụng':'Back to app'}</a><div class="settings-brand"><span>N</span><div><strong>${lang==='vi'?'Cài đặt Nolane':'Nolane Settings'}</strong><small>${categories.length} ${lang==='vi'?'nhóm khả dụng':'categories available'}</small></div></div><label class="settings-search"><span class="sr-only">${lang==='vi'?'Tìm cài đặt':'Search settings'}</span>${icon('search',{size:15})}<input type="search" placeholder="${lang==='vi'?'Tìm cài đặt…':'Search settings…'}" value="${esc(state.query??'')}" data-settings-search autocomplete="off"></label><div class="experience-switch experience-switch--four" role="group" aria-label="${lang==='vi'?'Tầng trải nghiệm':'Experience level'}">${EXP.map(([id,name,desc])=>`<button type="button" data-experience="${id}" aria-pressed="${exp===id}"><strong>${lang==='vi'?(VI_EXPERIENCE_NAMES[id]??name):name}</strong><small>${lang==='vi'?desc:({everyday:'Chat, projects, simple tools',workspace:'Missions, approvals, live progress',studio:'Files, terminal, diffs, activity',expert:'Full backend control plane'}[id])}</small></button>`).join('')}<button class="sr-only" data-experience="standard">${lang==='vi'?'Tiêu chuẩn':'Standard'}</button><button class="sr-only" data-experience="research">${lang==='vi'?'Nghiên cứu':'Research'}</button></div><nav>${categories.map(item=>`<a href="#settings-${esc(item.id)}" data-settings-category-link="${esc(item.id)}"${item.id===state.activeCategory?' aria-current="true"':''}><span aria-hidden="true" class="settings-nav__icon">${icon(item.id==='appearance'?'spark':item.id==='permissions'?'shield':item.id==='models'?'model':item.id==='terminal'?'terminal':item.id==='git'?'branch':item.id==='browser'?'globe':item.id==='integrations'?'tool':item.id==='diagnostics'?'activity':'settings',{size:14})}</span><span>${esc(categoryTitle(item,lang))}</span></a>`).join('')}</nav><footer><button type="button" data-settings-action="export">${lang==='vi'?'Xuất cài đặt':'Export settings'}</button><button type="button" data-settings-action="reset-layout">${lang==='vi'?'Đặt lại bố cục':'Reset layout'}</button></footer></aside><main class="settings-content" data-scroll-key="settings-content"><div class="settings-toolbar"><div><p class="eyebrow">Nolane Agent</p><h1>${lang==='vi'?'Cài đặt':'Settings'}</h1><p>${exp==='expert'?(lang==='vi'?'Toàn bộ quyền điều khiển backend, định tuyến, bằng chứng và hệ thống thử nghiệm.':'Full backend controls, routing evidence, resources, and experimental systems.'):(lang==='vi'?'Điều chỉnh trải nghiệm, giao diện và cách AI làm việc cùng bạn.':'Tune the experience, appearance, and how the agent works with you.')}</p></div><div class="settings-actions">${scopeOptions(state,lang)}<button type="button" data-settings-action="reset"${state.action?' disabled':''}>${lang==='vi'?'Đặt lại':'Reset scope'}</button><button type="button" class="primary" data-settings-action="save"${state.saving||!state.dirty?' disabled':''}>${state.saving?(lang==='vi'?'Đang lưu…':'Saving…'):state.dirty?(lang==='vi'?'Lưu thay đổi':'Save changes'):(lang==='vi'?'Đã lưu':'Saved')}</button></div></div><div class="settings-live-status" role="status" aria-live="polite" aria-atomic="true">${esc(statusLabel(state.statusMessage??(lang==='vi'?'Cài đặt đã sẵn sàng.':'Settings are ready.'),lang))}</div>${state.warnings?.length?`<div class="settings-warning" role="note">${lang==='vi'?`<strong>Cài đặt bị quản lý:</strong> ${state.warnings.length} tùy chỉnh bị chính sách bỏ qua.`:`<strong>Managed settings:</strong> ${state.warnings.length} override${state.warnings.length===1?'':'s'} ignored by policy.`}</div>`:''}${state.errors?.length?`<div class="settings-warning settings-warning--error" role="alert">${esc(state.errors[0].message)}</div>`:''}<div class="settings-sections">${categories.map(item=>renderCategory(item,state,lang)).join('')||`<p class="settings-empty">${lang==='vi'?'Không có cài đặt phù hợp với tìm kiếm.':'No settings match your search.'}</p>`}</div></main></section>`}
export function createSettingsModel(initial={}){let state=Object.freeze({appearance:'system',language:'system',performanceProfile:'auto',defaultIntent:'build',notifications:true,worktreeLocation:'default',...initial});const profiles=new Set(['lite','balanced','performance','auto']);return Object.freeze({update(patch={}){if(patch.performanceProfile&&!profiles.has(patch.performanceProfile))throw new Error('Unknown performance profile');state=Object.freeze({...state,...patch})},snapshot:()=>state})}
